CREATE OR REPLACE FUNCTION app_private.create_service_order_v432(p_ad_id uuid, p_description text, p_address text, p_from timestamp with time zone, p_to timestamp with time zone, p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor text:=app_private.verified_phone();ad public.specialist_announcements%rowtype;me public.profiles%rowtype;oid uuid;chat jsonb;begin
 if p_client_id is null then raise exception 'Request ID required';end if;perform pg_advisory_xact_lock(hashtext(actor),hashtext(p_client_id::text));
 select id into oid from public.service_orders where customer_phone=actor and client_request_id=p_client_id;if found then return jsonb_build_object('ok',true,'id',oid);end if;
 select * into ad from public.specialist_announcements where id=p_ad_id and status='approved';select * into me from public.profiles where phone=actor;
 if ad.id is null or ad.owner_phone=actor or public.is_user_blocked(actor,ad.owner_phone)then raise exception 'Specialist unavailable'using errcode='42501';end if;
 if not(coalesce(me.is_super_admin,false)or coalesce(me.admin_level='super',false))and(ad.city is distinct from me.city or not me.district=any(ad.target_districts))then raise exception 'Specialist outside selected area'using errcode='42501';end if;
 if length(trim(coalesce(p_description,'')))not between 3 and 3000 or length(trim(coalesce(p_address,'')))not between 3 and 500 then raise exception 'აღწერე სამუშაო და მიუთითე მისამართი.';end if;
 if app_private.has_external_contact_v432(p_description)then raise exception 'კომუნიკაციისთვის გამოიყენე აპის ჩათი; ნომერი ან გარე ბმული არ მიუთითო.';end if;
 if p_from is not null or p_to is not null then perform app_private.assert_arrival_v432(p_from,p_to);end if;chat:=public.start_direct_chat(actor,ad.owner_phone);
 if chat->>'ok'<>'true' or chat->>'id'is null then raise exception 'ჩათი ვერ გაიხსნა: %',coalesce(chat->>'message','შეამოწმე მიმოწერის პარამეტრები');end if;
 insert into public.service_orders(customer_phone,provider_phone,provider_name,category,description,address,requested_time,starting_price,status,workflow_version,client_request_id,thread_id,arrival_from,arrival_to)
 values(actor,ad.owner_phone,ad.owner_name,ad.title,trim(p_description),trim(p_address),p_from,ad.price,'consultation_requested',2,p_client_id,(chat->>'id')::uuid,p_from,p_to)returning id into oid;
 -- The order is the durable context; no automatic private message is sent on behalf of the customer.
 return jsonb_build_object('ok',true,'id',oid);end$function$

CREATE OR REPLACE FUNCTION app_private.legacy_start_direct_chat(p_phone text, p_other_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_phone text:=regexp_replace(coalesce(p_phone,''),'\D','','g');
  v_other text:=regexp_replace(coalesce(p_other_phone,''),'\D','','g');
  v_a text;v_b text;v_id uuid;
begin
  if v_phone='' or v_other='' or v_phone=v_other then return jsonb_build_object('ok',false,'message','მომხმარებელი არასწორადაა არჩეული');end if;
  if not exists(select 1 from public.profiles where phone=v_phone) or not exists(select 1 from public.profiles where phone=v_other) then
    return jsonb_build_object('ok',false,'message','პროფილი ვერ მოიძებნა');
  end if;
  if public.is_user_blocked(v_phone,v_other) then return jsonb_build_object('ok',false,'message','ამ მომხმარებელთან მიმოწერა დაბლოკილია');end if;
  v_a:=least(v_phone,v_other);v_b:=greatest(v_phone,v_other);
  insert into public.direct_chat_threads(user_a,user_b) values(v_a,v_b)
    on conflict(user_a,user_b) do update set updated_at=public.direct_chat_threads.updated_at returning id into v_id;
  insert into public.direct_chat_reads(thread_id,phone,last_read_at) values(v_id,v_phone,now())
    on conflict(thread_id,phone) do nothing;
  insert into public.direct_chat_reads(thread_id,phone,last_read_at) values(v_id,v_other,now())
    on conflict(thread_id,phone) do nothing;
  return jsonb_build_object('ok',true,'id',v_id);
end;
$function$

CREATE OR REPLACE FUNCTION app_private.manage_action_v433(p_kind text, p_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare city_name text;areas text[];actor text:=app_private.verified_phone();role_name text;old_data jsonb;begin
 role_name:=app_private.staff_info_v433()->>'role';
 if p_kind='posts'then select a.city,array[p.district],jsonb_build_object('body',p.content,'pinned',p.pinned)into city_name,areas,old_data from public.posts p left join public.profiles a on a.phone=p.author_phone where p.id=p_id for update of p;
 elsif p_kind='news'then select h.city,array[h.district],jsonb_build_object('title',h.title,'body',h.body)into city_name,areas,old_data from public.hot_news h where h.id=p_id and h.campaign_id is null for update;
 elsif p_kind='services'then select s.city,s.target_districts,jsonb_build_object('title',s.title,'body',s.body,'status',s.status)into city_name,areas,old_data from public.specialist_announcements s where s.id=p_id for update;
 elsif p_kind='campaigns'then select c.city,c.target_districts,jsonb_build_object('title',c.title,'body',c.body,'status',c.status)into city_name,areas,old_data from public.admin_campaigns c where c.id=p_id and c.status<>'deleted'for update;
 elsif p_kind='banners'then select p.city,array[p.district],jsonb_build_object('title',b.title)into city_name,areas,old_data from public.business_banners b join public.businesses x on x.id=b.business_id join public.profiles p on p.phone=x.owner_phone where b.id=p_id for update of b;
 else raise exception 'Invalid category';end if;
 if old_data is null or not app_private.staff_can_v433(p_kind,city_name,areas)then raise exception 'წვდომა არ გაქვს ან ჩანაწერი აღარ არსებობს'using errcode='42501';end if;
 if role_name='moderator'and(p_kind<>'posts'or p_action not in('edit','pin'))then raise exception 'Moderator may edit or pin posts only'using errcode='42501';end if;
 if p_data?'expected'and p_data->'expected'<>old_data then return jsonb_build_object('ok',false,'code','conflict');end if;
 if p_action='edit'then
 if p_kind='banners'or length(trim(coalesce(p_data->>'body','')))not between 1 and 5000 then raise exception 'ტექსტი უნდა იყოს 1–5000 სიმბოლო';end if;
 if p_kind<>'posts'and length(trim(coalesce(p_data->>'title','')))not between 1 and 160 then raise exception 'სათაური უნდა იყოს 1–160 სიმბოლო';end if;
 if p_kind='services'and app_private.has_external_contact_v432(coalesce(p_data->>'body','')||' '||coalesce(p_data->>'title',''))then raise exception 'გარე კონტაქტის გაზიარება დაუშვებელია';end if;
 if p_kind='posts'then update public.posts set content=trim(p_data->>'body')where id=p_id;
 elsif p_kind='news'then update public.hot_news set title=trim(p_data->>'title'),body=trim(p_data->>'body')where id=p_id;
 elsif p_kind='services'then update public.specialist_announcements set title=trim(p_data->>'title'),body=trim(p_data->>'body')where id=p_id;
 elsif p_kind='campaigns'then update public.admin_campaigns set title=trim(p_data->>'title'),body=trim(p_data->>'body'),revision=revision+1 where id=p_id;update public.hot_news set title=trim(p_data->>'title'),body=trim(p_data->>'body')where campaign_id=p_id;end if;
 elsif p_action='pin'and p_kind='posts'then update public.posts set pinned=coalesce((p_data->>'pinned')::boolean,false)where id=p_id;
 elsif p_action='delete'and p_kind in('posts','news','banners','campaigns')then
 if p_kind='posts'then delete from public.posts where id=p_id;
 elsif p_kind='news'then delete from public.hot_news where id=p_id;
 elsif p_kind='banners'then delete from public.business_banners where id=p_id;
 else update public.admin_campaigns set status='deleted',revision=revision+1 where id=p_id;end if;
 elsif p_action in('approve','reject')and p_kind='services'then
 if p_action='reject'and length(trim(coalesce(p_data->>'reason','')))<3 then raise exception 'მიუთითე უარყოფის მიზეზი';end if;
 update public.specialist_announcements set status=case p_action when 'approve'then 'approved'else 'rejected'end,review_note=case when p_action='reject'then trim(p_data->>'reason')else null end,reviewed_by=actor,reviewed_at=now()where id=p_id;
 else raise exception 'მოქმედება დაუშვებელია';end if;
 insert into app_private.moderation_audit_v433(actor,kind,target,action)values(actor,p_kind,p_id,p_action);return jsonb_build_object('ok',true);
end$function$

CREATE OR REPLACE FUNCTION app_private.staff_can_v433(kind text, city_name text, areas text[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare actor text:=app_private.verified_phone();s app_private.staff_scope_v433%rowtype;begin
 if exists(select 1 from public.profiles where phone=actor and(is_super_admin or admin_level='super'))then return true;end if;
 select * into s from app_private.staff_scope_v433 where phone=actor;
 return coalesce(s.city=city_name and areas=array[s.district]and(s.role='district'or(s.role='moderator'and kind='posts')),false);
end$function$
